Section HCW.
  Context {HCEIL : HeapCeil}.

Definition pv_W (lo : Z) (sp : word) (I R E : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (I, I + 8); (R, R + 4); (E, E + 24); (G_HTTP_CAT, G_HTTP_CAT + 64)]%Z.

Definition pv_post_r (r : pv_res) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (q I R E lo : Z) (bs : list byte) (r0 : Z) (E0 : ecv) (g : bool) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch (pv_W lo sp I R E) m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ bytes_at usegs m' q bs
    /\ rw_cells usegs m' I [C8 (wz (q + pv_adv r))]
    /\ rw_cells usegs m' R [C4 (wz (pv_result_cell r r0))]
    /\ rw_cells usegs m' E (ErrCodeCells (pv_ec r E0))
    /\ HttpCat m' (pv_cat r g) /\ XStatics m'.

Definition pv_post := fun ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc q I R E lo bs r0 E0 g m =>
  pv_post_r (pv_out bs) ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc q I R E lo bs r0 E0 g m.

Definition pv_pure (sp : word) (q I R E lo : Z) (bs : list byte) (r0 : Z) (E0 : ecv) : Prop :=
  ec_ok E0 /\ 0 <= r0 < 2^32 /\ lo + 80 <= bv_unsigned sp /\ 0xb8000 <= lo /\ ((0 < q /\ q + Z.of_nat (length bs) <= 0x10000) \/ 0x95090 <= q) /\ q + Z.of_nat (length bs) <= lo
  /\ bv_unsigned sp <= I /\ I + 8 <= 2^64 /\ bv_unsigned sp <= R /\ R + 4 <= 2^64 /\ bv_unsigned sp <= E /\ E + 24 <= 2^64
  /\ (I + 8 <= R \/ R + 4 <= I) /\ (I + 8 <= E \/ E + 24 <= I) /\ (R + 4 <= E \/ E + 24 <= R).

Definition pv_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (q I R E lo : Z) (bs : list byte) (r0 : Z) (E0 : ecv) (g : bool),
  bytes_at usegs m q bs ->
  rw_cells usegs m I [C8 (wz q)] ->
  rw_cells usegs m R [C4 (wz r0)] ->
  rw_cells usegs m E (ErrCodeCells E0) ->
  HttpCat m g -> XStatics m ->
  stk usegs m lo (bv_unsigned sp) ->
  pv_pure sp q I R E lo bs r0 E0 ->
  mem_inv usegs m ->
  evt usegs (pv_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc q I R E lo bs r0 E0 g m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz I) (wz (q + Z.of_nat (length bs))) (wz R) (wz E) a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_BP_PARSE_VERSION) fc None m (seg_rom usegs)).

