Definition pv_ctx (m m1 : mem) (sp s0v rav : word) (q I R E lo : Z) (bs : list byte) (itv resv : Z) (E0 : ecv) (g : bool)
    (j8 : list byte) (tmp : list cell) : Prop :=
  rw_cells usegs m1 (bv_unsigned sp + -48) [CB 8 j8]
  /\ rw_cells usegs m1 (bv_unsigned sp + -40) tmp
  /\ rw_cells usegs m1 (bv_unsigned sp + -16) [C8 s0v; C8 rav]
  /\ rw_cells usegs m1 I [C8 (wz itv)]
  /\ rw_cells usegs m1 R [C4 (wz resv)]
  /\ rw_cells usegs m1 E (ErrCodeCells E0)
  /\ HttpCat m1 g /\ XStatics m1
  /\ stk usegs m1 lo (bv_unsigned sp + -48)
  /\ bytes_at usegs m1 q bs
  /\ munch (pv_W lo sp I R E) m m1 /\ wmono usegs m m1 /\ mem_inv usegs m1.

