Lemma pv_tail : forall rax ra sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s0v s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (q I R E lo : Z) (bs : list byte) (itv resv r0 : Z) (E0 : ecv) (g : bool)
    (j8 : list byte) (e loc lcv : Z) (r : pv_res),
  pv_ctx m m1 sp s0v ra q I R E lo bs itv resv E0 true j8 [C8 (wz e); C8 (wz G_HTTP_CAT); C8 (wz 3)] ->
  pv_pure sp q I R E lo bs r0 E0 ->
  1 <= e < 2^31 -> 0 <= loc -> loc + 1 < 2^64 -> lcv = loc + 1 ->
  q + pv_adv r = itv -> pv_result_cell r r0 = resv -> pv_err r = Some (e, loc) -> 0 <= resv < 2^32 ->
  evt usegs (pv_post_r r ra sp gp tp s0v s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc q I R E lo bs r0 E0 g m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -48)) gp tp t0 t1 t2 (wz E) s1 (wz lcv) a1 a2 a3 a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x3eb00) fc None m1 (seg_rom usegs)).
